{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Report Defect",
        "actor": "Engineer (Issue Owner)",
        "system": "Issue Tracking System",
        "inputs": [
          "Defect observation",
          "Sample or lot context",
          "Initial evidence"
        ],
        "outputs": [
          "Defect record with description, sample/lot context, initial evidence, and customer impact assumption"
        ]
      },
      {
        "id": "A2",
        "name": "Conduct Triage Discussion",
        "actor": "Issue Owner, Process Engineer, Quality Engineer, Customer Interface Owner",
        "system": "Issue Tracking System",
        "inputs": [
          "Defect record"
        ],
        "outputs": [
          "Triage discussion notes",
          "Preliminary severity assessment",
          "Identification of required experiments"
        ]
      },
      {
        "id": "A3",
        "name": "Classify Severity and Assess Scope",
        "actor": "Quality Engineer",
        "system": "Issue Tracking System",
        "inputs": [
          "Triage discussion notes",
          "Defect record"
        ],
        "outputs": [
          "Classified severity level",
          "Affected scope determination"
        ]
      },
      {
        "id": "A4",
        "name": "Perform Additional Experiments",
        "actor": "Engineer (Issue Owner)",
        "system": "Issue Tracking System",
        "inputs": [
          "Triage discussion notes",
          "Classified severity level",
          "Affected scope determination"
        ],
        "outputs": [
          "Experiment results"
        ]
      },
      {
        "id": "A5",
        "name": "Review Experiment Results and Select Improvement Action",
        "actor": "Issue Owner",
        "system": "Issue Tracking System",
        "inputs": [
          "Experiment results",
          "Classified severity level",
          "Affected scope determination"
        ],
        "outputs": [
          "Selected improvement action",
          "Improvement decision record"
        ]
      },
      {
        "id": "A6",
        "name": "Perform Customer Risk Assessment",
        "actor": "Customer Interface Owner, Quality Engineer",
        "system": "Issue Tracking System",
        "inputs": [
          "Improvement decision record",
          "Classified severity level",
          "Customer impact assumption"
        ],
        "outputs": [
          "Customer risk assessment findings"
        ]
      },
      {
        "id": "A7",
        "name": "Produce Customer Risk Summary Report",
        "actor": "Manager",
        "system": "Risk Report Template",
        "inputs": [
          "Customer risk assessment findings",
          "Improvement decision record",
          "Classified severity level",
          "Affected scope determination"
        ],
        "outputs": [
          "Customer risk summary report",
          "Action item list"
        ]
      },
      {
        "id": "A8",
        "name": "Distribute Final Report and Action Items",
        "actor": "Manager",
        "system": "Issue Tracking System",
        "inputs": [
          "Customer risk summary report",
          "Action item list"
        ],
        "outputs": [
          "Distributed report and action items to internal stakeholders"
        ]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Is the defect customer-impacting?",
        "branches": [
          {
            "outcome": "Yes",
            "next": "A6"
          },
          {
            "outcome": "No",
            "next": "A7"
          }
        ]
      }
    ],
    "exceptions": [
      {
        "id": "E1",
        "description": "No defined escalation or emergency path exists for critical or safety-related defects. The process does not specify mandatory approvals or external notifications for such cases.",
        "handling": "Gap — no exception handling defined in current workflow"
      }
    ],
    "dependencies": [
